    parser:new C.StreamParser(512),verified:false,pidFault:null,pid:null,pidAt:0,fast:null,slow:null,fastAt:0,slowAt:0,
    locked:null,balance:null,fw:null,firmware:'—',phase:'IDLE',id:0,baseline:null,candidate:null,
