  async function exclusive(fn){if(S.busy)throw Error('另一项固件操作正在等待确认');const epoch=S.epoch;S.busy=true;update();try{return await fn();}finally{if(epoch===S.epoch)S.busy=false;update();}}
  async function manualPid(){return exclusive(async()=>{requireLink();if(S.locked||S.fw!==0)throw Error('训练锁定或活动事务期间不能人工调参');const p=inputPid();await readPid({fw:0,lock:false});if(!confirm('确认将六个 PID 写入小车？完成后将核对 ACK 和 PID 读回。'))return;await ack(C.manualSet(p),'MSET');await settledPid({pid:p,fw:0,lock:false});clearCandidate();S.metrics=null;status('人工 PID 已获 ACK，且六个参数读回一致');toast('参数已确认生效');});}
