    $('pidIntegrity').textContent=S.pidFault||(!S.pid?'等待小车六参数读回':'六参数数值范围检查通过；参数是否生效以 ACK 和读回一致为准');
    updateContinuous();$('workflowHint').textContent=!known?'先连接并确认固件与PID':!S.balance?'按小车硬件流程启动平衡':A.running?'自动采集、应用和评价；保持Bluefy前台':'配置接口后启动，LLM调参全程自动；人工PID仍在PID页';
    document.querySelectorAll('[data-step]').forEach(el=>{const key=el.dataset.step;el.classList.toggle('done',key==='lock'?!!S.locked:key==='baseline'?!!S.metrics:key==='review'?!!S.candidate:key==='trial'?!!S.id:false);});
